<script setup lang="ts">
import {computed,shallowRef,watch} from 'vue'
import {Table as ATable,Modal as AModal,Descriptions as ADescriptions,DescriptionsItem as ADescriptionsItem,Tag as ATag} from 'ant-design-vue'
import {correlationFields,correlationStates,type CorrelationDefinition,type CorrelationResult,type CorrelationWindow} from '../correlation'
import {formatTime} from '../types'
const props=defineProps<{result:CorrelationResult;definition:CorrelationDefinition;detailID?:string}>(),emit=defineEmits<{close:[]}>()
const selected=shallowRef<CorrelationWindow|null>(null),copyError=shallowRef('')
watch(()=>[props.result,props.detailID],()=>{selected.value=props.result.windows.find(w=>w.detection_id===props.detailID)??null;copyError.value=''},{immediate:true})
const rows=computed(()=>props.result.windows),columns=[{title:'窗口时间',key:'time',width:210},{title:'接入探针 / 注册代次',key:'sensor',width:220},{title:'分组值',dataIndex:'group_value',width:200},{title:'告警条数',dataIndex:'count',width:100},{title:'计量值 / 阈值',key:'metric',width:145},{title:'窗口状态',key:'status',width:180},{title:'操作',key:'action',width:100,fixed:'right' as const}]
function close(){selected.value=null;copyError.value='';emit('close')}
async function copy(value:string){copyError.value='';try{if(!navigator.clipboard)throw new Error();await navigator.clipboard.writeText(value)}catch{copyError.value='无法访问剪贴板，请手动选择并复制事件标识。'}}
</script>
<template>
 <div class="correlation-totals"><span>唯一告警 <strong>{{result.unique_events}}</strong></span><span>回测输入去重 <strong>{{result.duplicate_events}}</strong></span><span>分组字段缺失 <strong>{{result.missing_group}}</strong></span><span>观察到阈值 <strong>{{result.threshold_windows}}</strong> 个窗口</span><span>边界窗口 <strong>{{result.partial_windows}}</strong></span></div>
 <div class="table-wrap"><a-table :columns="columns" :data-source="rows" row-key="detection_id" :pagination="{pageSize:20,showSizeChanger:false}" size="small" :scroll="{x:1155}"><template #bodyCell="{column,record}"><template v-if="column.key==='time'">{{formatTime(record.start)}}<div class="page-description">至 {{formatTime(record.end)}}</div></template><template v-else-if="column.key==='sensor'"><span class="technical correlation-wrap">{{record.sensor_id}}</span><div class="page-description technical correlation-wrap">{{record.sensor_registration_id}}</div></template><span v-else-if="column.dataIndex==='group_value'" class="technical correlation-wrap">{{record.group_value}}</span><template v-else-if="column.key==='metric'">{{record.metric_value}} / {{definition.threshold}}<div v-if="record.missing_metric" class="page-description">{{record.missing_metric}} 条计量值未知</div></template><a-tag v-else-if="column.key==='status'" :color="record.status==='threshold_observed'?'warning':undefined">{{correlationStates[record.status]}}</a-tag><a-button v-else-if="column.key==='action'" type="link" size="small" @click="selected=record as CorrelationWindow;copyError=''">查看证据</a-button></template><template #emptyText><span>快照中没有可计入窗口的告警，此结果不代表流量安全。</span></template></a-table></div>
 <a-modal v-if="selected" :open="true" title="窗口证据" :width="820" :body-style="{maxHeight:'calc(100vh - 240px)',overflowY:'auto'}" @cancel="close"><a-alert type="info" show-icon message="窗口只描述检索快照中已观察到的事实；来源覆盖未经证明，不据此认定攻击成功或授予处置权限。" class="section-gap"/><a-descriptions bordered :column="1" size="small"><a-descriptions-item label="窗口状态"><a-tag :color="selected.status==='threshold_observed'?'warning':undefined">{{correlationStates[selected.status]}}</a-tag></a-descriptions-item><a-descriptions-item label="探针 / 注册代次">{{selected.sensor_id}} / {{selected.sensor_registration_id}}</a-descriptions-item><a-descriptions-item :label="correlationFields[definition.group_by]">{{selected.group_value}}</a-descriptions-item><a-descriptions-item label="时间区间">{{formatTime(selected.start)}} — {{formatTime(selected.end)}}，结束时间不计入</a-descriptions-item><a-descriptions-item label="计量 / 阈值">{{selected.metric_value}} / {{definition.threshold}}；{{selected.count}} 条唯一告警，{{selected.missing_metric}} 条计量值未知</a-descriptions-item><a-descriptions-item label="窗口标识"><span class="technical correlation-wrap">{{selected.detection_id}}</span></a-descriptions-item><a-descriptions-item label="完整证据集合摘要"><span class="technical correlation-wrap">{{selected.evidence_sha256}}</span></a-descriptions-item></a-descriptions><h3 class="correlation-evidence-title">证据样本 · {{selected.evidence.length}} / {{selected.count}}</h3><p class="page-description">{{selected.evidence_truncated?'当前展示按事件标识排序的前 8 条证据；计量和摘要包含全部窗口事实。':'当前展示全部窗口证据。'}} 相同标识的补证据不形成新的窗口身份。</p><a-alert v-if="copyError" type="warning" show-icon :message="copyError" class="section-gap"/><ol class="correlation-evidence"><li v-for="item in selected.evidence" :key="item.event_id"><div class="correlation-evidence-header"><strong class="technical correlation-wrap">{{item.event_id}}</strong><a-button size="small" @click="copy(item.event_id)">复制事件标识</a-button></div><span>{{formatTime(item.timestamp)}}</span><div class="page-description technical correlation-wrap">原文 SHA-256：{{item.raw_sha256}}</div></li></ol><template #footer><a-button @click="close">关闭</a-button></template></a-modal>
</template>
<style scoped>:deep(.ant-descriptions-item-content){overflow-wrap:anywhere}.correlation-totals{display:flex;gap:12px;flex-wrap:wrap;padding:12px 16px;border-bottom:1px solid var(--line)}.correlation-totals strong{font-variant-numeric:tabular-nums}.correlation-wrap{overflow-wrap:anywhere}.correlation-evidence-title{font-size:14px;margin:14px 0 8px}.correlation-evidence{padding-left:20px;margin:8px 0}.correlation-evidence li{padding:10px 0;border-bottom:1px solid var(--line)}.correlation-evidence-header{display:flex;gap:8px;align-items:flex-start;justify-content:space-between}.correlation-evidence-header>strong{min-width:0}.correlation-evidence-header>.ant-btn{flex-shrink:0}</style>
